import GameBoy

// Sliding puzzle: the Swift logo is cut into 3x3 pieces and the bottom-right one is removed.
// START shuffles the board; the D-pad slides the piece next to the empty slot in that direction.
// Build with `gb-rom --color` to get the logo in Swift orange on a Game Boy Color.
// The picture data in Logo.swift is generated by tools/genlogo.py.

enum Direction {
  case up, down, left, right

  /// The direction of the first D-pad button found in `buttons`, if any
  init?(_ buttons: Joypad) {
    if buttons.contains(.up) { self = .up }
    else if buttons.contains(.down) { self = .down }
    else if buttons.contains(.left) { self = .left }
    else if buttons.contains(.right) { self = .right }
    else { return nil }
  }

  var opposite: Direction {
    switch self {
    case .up: .down
    case .down: .up
    case .left: .right
    case .right: .left
    }
  }
}

struct Board {
  static let side = 3
  static let cellCount = side * side
  /// The piece that is taken out to make room (the bottom-right one)
  static let emptyPiece = UInt8(cellCount - 1)

  /// The piece in each cell, row by row. The board is solved when `cells[i] == i` everywhere
  private(set) var cells: [UInt8] = Array(0..<UInt8(cellCount))
  /// The cell that holds `emptyPiece`
  private(set) var emptyCell = cellCount - 1

  var isSolved: Bool {
    for i in 0..<Board.cellCount where cells[i] != i { return false }
    return true
  }

  /// Slides the piece next to the empty slot in `direction`.
  /// Returns the cell the piece came from (now empty), or nil if there is no piece on that side
  mutating func slide(_ direction: Direction) -> Int? {
    let x = emptyCell % Board.side, y = emptyCell / Board.side
    let source: Int
    switch direction {
    case .up: if y == Board.side - 1 { return nil }; source = emptyCell + Board.side
    case .down: if y == 0 { return nil }; source = emptyCell - Board.side
    case .left: if x == Board.side - 1 { return nil }; source = emptyCell + 1
    case .right: if x == 0 { return nil }; source = emptyCell - 1
    }
    cells.swapAt(source, emptyCell)
    emptyCell = source
    return source
  }
}

// --- Screen layout and tiles ---

enum Tile {
  static let frame = 1          // 8 tiles: corners and edges, see frameTiles
  static let empty: UInt8 = 9
  static let logo = 0x80
}

/// Tiles per piece side (a piece is 32x32 pixels)
let pieceSize = Logo.side / Board.side
let boardX = 4, boardY = 2
let textX = 4, titleY = 0, statusY = 16

// 1bpp tiles: the frame around the board (top-left, top, top-right, left, right, bottom-left, bottom,
// bottom-right) followed by the empty slot
let frameTiles: [UInt8] = [
  0x00, 0x00, 0x00, 0x00, 0x00, 0x07, 0x07, 0x06,
  0x00, 0x00, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0x00,
  0x00, 0x00, 0x00, 0x00, 0x00, 0xE0, 0xE0, 0x60,
  0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06, 0x06,
  0x60, 0x60, 0x60, 0x60, 0x60, 0x60, 0x60, 0x60,
  0x06, 0x07, 0x07, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x00, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x00, 0x00,
  0x60, 0xE0, 0xE0, 0x00, 0x00, 0x00, 0x00, 0x00,
  0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
]

func drawFrame() {
  let left = boardX - 1, right = boardX + Logo.side
  let top = boardY - 1, bottom = boardY + Logo.side
  for i in 0..<Logo.side {
    Display.setBackgroundTile(x: boardX + i, y: top, UInt8(Tile.frame + 1))
    Display.setBackgroundTile(x: boardX + i, y: bottom, UInt8(Tile.frame + 6))
    Display.setBackgroundTile(x: left, y: boardY + i, UInt8(Tile.frame + 3))
    Display.setBackgroundTile(x: right, y: boardY + i, UInt8(Tile.frame + 4))
  }
  Display.setBackgroundTile(x: left, y: top, UInt8(Tile.frame))
  Display.setBackgroundTile(x: right, y: top, UInt8(Tile.frame + 2))
  Display.setBackgroundTile(x: left, y: bottom, UInt8(Tile.frame + 5))
  Display.setBackgroundTile(x: right, y: bottom, UInt8(Tile.frame + 7))
}

/// Draws one cell of the board. The empty slot is drawn as a hole unless `complete` is set
func draw(cell: Int, of board: Board, complete: Bool = false) {
  let piece = board.cells[cell]
  let x = boardX + cell % Board.side * pieceSize
  let y = boardY + cell / Board.side * pieceSize
  // Top-left tile of the piece within the picture
  let origin = Int(piece) / Board.side * pieceSize * Logo.side + Int(piece) % Board.side * pieceSize
  let hole = piece == Board.emptyPiece && !complete
  for ty in 0..<pieceSize {
    for tx in 0..<pieceSize {
      let tile = hole ? Tile.empty : UInt8(Tile.logo) + Logo.map[origin + ty * Logo.side + tx]
      Display.setBackgroundTile(x: x + tx, y: y + ty, tile)
    }
  }
}

func drawAll(_ board: Board, complete: Bool = false) {
  for cell in 0..<Board.cellCount { draw(cell: cell, of: board, complete: complete) }
}

func showMoves(_ moves: Int) {
  Console.setCursor(x: textX, y: statusY)
  Console.write("MOVES "); Console.write(moves)
}

/// Shuffles by sliding random pieces (so the puzzle always stays solvable), showing every move
func shuffle(_ board: inout Board) {
  var last: Direction? = nil
  repeat {
    var remaining = 60
    while remaining > 0 {
      let direction: Direction = switch Random.next() & 3 {
      case 0: .up
      case 1: .down
      case 2: .left
      default: .right
      }
      // Do not undo the previous move
      if let last, direction == last.opposite { continue }
      let hole = board.emptyCell
      guard let source = board.slide(direction) else { continue }
      Display.waitVBlank()
      draw(cell: hole, of: board)
      draw(cell: source, of: board)
      last = direction
      remaining -= 1
    }
  } while board.isSolved
}

// --- Main ---

enum State { case title, playing, solved }

Console.initialize()
Display.turnOff()
Display.loadTiles1bpp(frameTiles, startingAt: Tile.frame)
Display.loadTiles(Logo.tiles, startingAt: Tile.logo)
// Game Boy Color: white, a blend for the smoothed edges, the Swift orange, and a dark color for the text,
// the frame and the empty slot. The original Game Boy shows the same tiles in four shades
Display.setBackgroundColors([.white, Color(rgb: 0xF8A89C), Color(rgb: 0xF05138), Color(rgb: 0x282830)])

var board = Board()
var state = State.title
var moves = 0
var frames: UInt16 = 0

drawFrame()
drawAll(board, complete: true)
Console.write("SWIFT PUZZLE", x: textX, y: titleY)
Console.write("PRESS START", x: textX, y: statusY)
Display.turnOn()

while true {
  Display.waitVBlank()
  Joypad.poll()
  frames &+= 1
  let pressed = Joypad.pressed

  switch state {
  case .title, .solved:
    guard pressed.contains(.start) else { break }
    // The time it took the player to press START makes the shuffle unpredictable
    Random.seed(frames ^ UInt16(HW.div) << 8)
    board = Board()
    draw(cell: board.emptyCell, of: board)
    Console.write("SWIFT PUZZLE", x: textX, y: titleY)
    Console.write("SHUFFLING...", x: textX, y: statusY)
    shuffle(&board)
    moves = 0
    Console.write("MOVES 0     ", x: textX, y: statusY)
    state = .playing

  case .playing:
    guard let direction = Direction(pressed) else { break }
    let hole = board.emptyCell
    guard let source = board.slide(direction) else { break }   // nothing to slide on that side
    draw(cell: hole, of: board)
    draw(cell: source, of: board)
    moves += 1
    showMoves(moves)
    if board.isSolved {
      draw(cell: board.emptyCell, of: board, complete: true)
      Console.write("  SOLVED!   ", x: textX, y: titleY)
      state = .solved
    }
  }
}
